<template id="line-template"><tr><td class="line-number"></td><td><select data-name="account_id" required><option value="">Select account</option>@foreach($accounts as $a)<option value="{{ $a->id }}">{{ $a->code }} · {{ $a->name }}</option>@endforeach</select></td><td><input data-name="description" placeholder="Line narration"></td><td><input data-name="debit" class="amount debit" type="number" step="0.01" min="0"></td><td><input data-name="credit" class="amount credit" type="number" step="0.01" min="0"></td><td><button type="button" class="remove-line">×</button></td></tr></template>
<script>
(()=>{const body=document.getElementById('line-body'),tpl=document.getElementById('line-template'),base='{{ $company->base_currency }}';
function renumber(){[...body.rows].forEach((row,i)=>{row.querySelector('.line-number').textContent=i+1;row.querySelectorAll('[name],[data-name]').forEach(el=>{const key=el.dataset.name||((el.name.match(/\]\[([^\]]+)\]$/)||[])[1]);if(key)el.name=`lines[${i}][${key}]`;});});totals();}
function totals(){let d=0,c=0;body.querySelectorAll('.debit').forEach(x=>d+=parseFloat(x.value)||0);body.querySelectorAll('.credit').forEach(x=>c+=parseFloat(x.value)||0);document.getElementById('debit-total').textContent=d.toFixed(2);document.getElementById('credit-total').textContent=c.toFixed(2);const s=document.getElementById('balance-state'),ok=d>0&&Math.round(d*100)===Math.round(c*100);s.textContent=ok?'BALANCED':'OUT OF BALANCE';s.className='journal-status '+(ok?'posted':'reversed');}
document.getElementById('add-line').addEventListener('click',()=>{body.appendChild(tpl.content.cloneNode(true));renumber();});
body.addEventListener('click',e=>{if(e.target.classList.contains('remove-line')){if(body.rows.length<=2)return alert('A journal requires at least two lines.');e.target.closest('tr').remove();renumber();}});
body.addEventListener('input',e=>{if(e.target.classList.contains('debit')&&parseFloat(e.target.value)>0)e.target.closest('tr').querySelector('.credit').value='';if(e.target.classList.contains('credit')&&parseFloat(e.target.value)>0)e.target.closest('tr').querySelector('.debit').value='';totals();});
document.getElementById('currency_code').addEventListener('change',e=>{if(e.target.value===base)document.getElementById('exchange_rate').value='1';});renumber();})();
</script>
